def anidar(plano: dict) -> dict:
    """
    Convierte un diccionario de claves con puntos en un diccionario anidado.

    Ejemplo: {'a.b': 1} -> {'a': {'b': 1}}

    Args:
        plano: Un diccionario donde las claves son strings con puntos '.'

    Returns:
        Un diccionario anidado con las claves separadas por puntos.
    """
    result = {}
    for key, value in plano.items():
        if '.' in key:
            parts = key.split('.')
            current = result
            for part in parts[:-1]:
                current = current.setdefault(part, {})
            current[parts[-1]] = value
        else:
            result[key] = value
    return result


